  rw [ h_cauchy, mul_div_cancel₀ _ ( Finset.prod_ne_zero_iff.mpr fun i hi => Finset.prod_ne_zero_iff.mpr fun j hj => sub_ne_zero.mpr ( hzy i j ) ) ]

